mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ t.F_TRADE_ID outTradeId, /*外部成交编号*/ deal1.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetName,/**资产简称**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE effDate,/**交割日期**/ t.INV_AIM invAim,/**投资目的**/ t.PRIN_AMT capital,/**本金金额**/ t.CPRICE_AMT cpriceAmt,/**净价总额**/ t.INT_AMT intAmt,/**应收利息总额**/ t.UNIT_CPRICE*100 cprice,/**净价**/ t.CCY ccy,/**币种**/ t.FPRICE_AMT settleAmt,/**结算金额**/ t.MY_ACCT_NO myAcctNo,/**资金账户**/ d.GEN_TYPE dataSource /**数据来源**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN TRD_PRODUCT_DEAL_ADD d on t.TRADE_ID = d.TRADE_ID LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal1.BOOKSET_ID where t.BUSI_TYPE =#{BUSI_TYPE_09} and t.FINPROD_TYPE = #{FINPRODUCT_TYPE_F17}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal1.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_ID IN
#{assetId}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
AND d.GEN_TYPE IN
#{dataSource}
order by t.TRADE_ID desc
